import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"大畜","description":"周易集解 - 大畜","frontmatter":{"title":"大畜","description":"周易集解 - 大畜"},"headers":[],"relativePath":"classics/jijie/026.md","filePath":"classics/jijie/026.md"}'),l={name:"classics/jijie/026.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大畜" tabindex="-1">大畜 <a class="header-anchor" href="#大畜" aria-label="Permalink to “大畜”">​</a></h1><h2 id="大畜-1" tabindex="-1">大畜 <a class="header-anchor" href="#大畜-1" aria-label="Permalink to “大畜”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>大畜，利貞。不家食，吉。利涉大川。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：有無妄然後可畜也，故受之以大畜。</p><p>崔憬曰：有誠實，則可以中心藏之，故言有無妄然後可畜也。</p><p>虞翻曰：大壯初之上，其德剛上也。與萃旁通。二五失位，故利貞。此萃五之復二，成臨。臨者，大也。至上有頤養之象，故名大畜也。</p><p>虞翻曰：二稱家，謂二五易位，成家人。家人體噬嗑食，故｢利涉大川，應乎天也｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：大畜，剛健篤實，輝光日新。其德剛上而尚賢。能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：剛健謂乾，篤實謂艮。二已之五，利涉大川。互體離坎，離為日，故｢輝光日新｣也。</p><p>蜀才曰：此本大壯卦。</p><p>案：剛自初升，為主於外。剛陽居上，尊尚賢也。</p><p>虞翻曰：健，乾。止，艮也。二五易位，故大正。舊讀言能止健，誤也。</p><p>虞翻曰：二五易位成家人。今體頤養象，故｢不家食吉，養賢也｣。</p><p>案：乾為賢人也，艮為宮闕也，令賢人居於闕下，不家食之象。</p><p>京房曰：謂二變五體坎，故利涉大川。五天位，故曰｢應乎天｣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天在山中，大畜。君子以多識前言往行，以畜其德。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>向秀曰：止莫若山，大莫若天，天在山中，大畜之象。天為大器，山則極止，能止大器，故名大畜也。</p><p>虞翻曰：君子謂乾。乾為言，震為行，坎為志識；乾知大始，震在乾前，故｢識前言往行｣。有頤養象，故｢以畜其德｣矣。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，有厲，利已。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>王弼曰：四乃畜已，未可犯也。進則災危，有厲則止，故能利已。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有厲利已，不犯災也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂二變正，四體坎，故稱災也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，輿說輹。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：萃坤為車，為輹；坤消乾成，故｢車說腹。｣腹，或作輹也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：輿說輹，中無尤也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>盧氏曰：乾為輿。</p><p>案：輹，車之鉤心。夾軸之物。處失其正，上應於五。五居畜盛，止不我升，故且說輹停留。待時而進退，得正，故無尤也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，良馬逐，利艱貞，吉。日閑輿衛，利有攸往。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：乾為良馬，震為驚走，故稱逐也。謂二已變，三在坎中，故利艱貞吉。離為日。二至五，體師象。坎為閑習，坤為車輿；乾人在上，震為驚衛，講武閑兵，故曰｢日閑輿衛｣也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：利有攸往，上合志也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂上應也。五已變正，上動成坎，坎為志，故｢利有攸往，與上合志也｣。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，童牛之牯，元吉。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：艮為童。五已之正。萃坤為牛。牯謂以木楅其角。大畜，畜物之家，惡其觸害。艮為手，為小木。巽為繩。繩縛小木，橫著牛角，故曰｢童牛之牯｣。得位承五，故元吉而喜，喜，謂五也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六四元吉，有喜也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：坤為輿，故有牛矣。牿，楅也。以木為之，橫施於角，止其觝之威也。初欲上進，而四牿之。角既被牿，則不能觸四，是四童初之角也。四能牿初，與無角同，所以元吉而有喜矣。童牛，無角之牛也。《封人職》曰：設其楅衡。註雲：楅設於角，衡設於鼻，止其觝觸也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，豶豕之牙，吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：二變時，坎為豕。劇豕稱豶。令不害物。三至上，體頤象。五變之剛，巽為白；震為出；剛白從頤中出，牙之象也。動而得位，｢豶豕之牙，吉｣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六五之吉，有慶也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：五變得正，故有慶也。</p><p>崔憬曰：《說文》：豶，劇豕。今俗猶呼劇豬是也。然以豕本剛突，劇乃性和，雖有其牙，不足害物，是制於人也。以喻九二之剛健失位，若豕之劇，不足畏也；而六五應止之易，故吉有慶矣。</p><p>案：九二坎爻，坎為豕也。以陽居陰，而失其位，若豕被劇之象也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，何天之衢，享。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：何，當也。衢，四交道。乾為天，震艮為道。以震交艮，故｢何天之衢，亨｣。上變，坎為亨也。</p><p>王弼曰：處畜之極，畜極則亨。何，辭也。猶雲何畜，乃天之衢。亨，道大行也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：何天之衢，道大行也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂上據二陰。乾為天道，震為行，故｢道大行矣｣</p>',76)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
